"""A least-recently-used cache."""
import time
from collections import OrderedDict


USE_DEFAULT = object()


class LRUCache:
    def __init__(self, capacity, ttl=None, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self._validate_ttl(ttl)
        self.capacity = capacity
        self.ttl = ttl
        self._clock = clock
        self._items = OrderedDict()

    @staticmethod
    def _validate_ttl(ttl):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be greater than 0 or None")

    def _purge_expired(self):
        now = self._clock()
        expired = [
            key for key, (_, stored_at, ttl) in self._items.items()
            if ttl is not None and now - stored_at >= ttl
        ]
        for key in expired:
            del self._items[key]

    def get(self, key, default=None):
        """Return the value and mark the entry as most recently used."""
        self._purge_expired()
        if key not in self._items:
            return default
        self._items.move_to_end(key)
        return self._items[key][0]

    def peek(self, key, default=None):
        """Return the value without touching the order."""
        self._purge_expired()
        item = self._items.get(key)
        return default if item is None else item[0]

    def put(self, key, value, ttl=USE_DEFAULT):
        entry_ttl = self.ttl if ttl is USE_DEFAULT else ttl
        self._validate_ttl(entry_ttl)
        self._purge_expired()
        stored_at = self._clock()
        if key in self._items:
            self._items.move_to_end(key)
        elif len(self._items) >= self.capacity:
            self._items.popitem(last=False)
        self._items[key] = (value, stored_at, entry_ttl)

    def keys(self):
        """Keys from least to most recently used."""
        self._purge_expired()
        return list(self._items)

    def __contains__(self, key):
        self._purge_expired()
        return key in self._items

    def __len__(self):
        self._purge_expired()
        return len(self._items)
